mapper.select:
select l.fund_log_id, l.account_id, a.account_name, l.biz_type, l.bill_id, l.bill_no,
       l.direction, l.change_amount, l.before_balance, l.after_balance, l.biz_date,
       l.counterparty_name, l.remark, l.create_by, l.create_time
from fin_fund_log l
left join fin_fund_account a on a.account_id = l.account_id

    and l.account_id = #{accountId}
    and l.biz_type = #{bizType}
    and l.direction = #{direction}
    and l.bill_no like concat('%', #{billNo}, '%')

order by l.create_time desc, l.fund_log_id desc

select transfer_id, transfer_no, out_account_id, in_account_id, amount, fee_amount, transfer_date,
       status, audit_by, audit_time, remark, create_by, create_time, update_by, update_time
from fin_fund_transfer

    and transfer_no like concat('%', #{transferNo}, '%')
    and out_account_id = #{outAccountId}
    and in_account_id = #{inAccountId}
    and status = #{status}

order by create_time desc, transfer_id desc
